// backend/src/controllers/exportController.js
// Returns the batch results JSON for evaluation purposes.
// Reads the file generated by scripts/run_batch.js.

const fs = require('fs');
const path = require('path');

const RESULTS_PATH = path.resolve(__dirname, '../../backend', 'metrics', 'batch_results.json');

async function getExportResults(req, res, next) {
  try {
    if (!fs.existsSync(RESULTS_PATH)) {
      return res.status(404).json({ error: { code: 'NOT_FOUND', message: 'Batch results not found' } });
    }
    const data = JSON.parse(fs.readFileSync(RESULTS_PATH, 'utf8'));
    res.json(data);
  } catch (err) {
    next(err);
  }
}

module.exports = { getExportResults };
